BEGIN;
CREATE SCHEMA erp_contracting_private;
REVOKE ALL ON SCHEMA erp_contracting_private FROM PUBLIC,anon,authenticated,service_role;
ALTER TABLE public.erp_contracting_documents DROP CONSTRAINT erp_contracting_documents_kind_check;
ALTER TABLE public.erp_contracting_documents ADD CONSTRAINT erp_contracting_documents_kind_check CHECK(kind IN('bid','project','cost_sheet','quotation','contract','certificate','reverse_certificate','work_item'));
CREATE TABLE public.erp_contracting_reversals(cafe_id uuid NOT NULL,document_id uuid NOT NULL,source_id uuid NOT NULL,credit_note_id uuid,credit_document_id uuid,allocation_id uuid,PRIMARY KEY(cafe_id,document_id),UNIQUE(credit_note_id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.erp_contracting_documents(cafe_id,id) ON DELETE CASCADE,FOREIGN KEY(cafe_id,source_id) REFERENCES public.erp_contracting_documents(cafe_id,id),FOREIGN KEY(cafe_id,credit_note_id) REFERENCES public.bf_credit_notes(cafe_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(cafe_id,credit_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,allocation_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_contracting_reverse_lines(cafe_id uuid NOT NULL,document_id uuid NOT NULL,line_id uuid NOT NULL,invoice_line_id uuid NOT NULL,quantity numeric(18,3) NOT NULL CHECK(quantity>0),net numeric(18,2) NOT NULL CHECK(net>=0),tax numeric(18,2) NOT NULL CHECK(tax>=0),PRIMARY KEY(cafe_id,document_id,line_id),UNIQUE(cafe_id,document_id,invoice_line_id),FOREIGN KEY(cafe_id,document_id,line_id) REFERENCES public.erp_contracting_lines(cafe_id,document_id,id) ON DELETE CASCADE,FOREIGN KEY(cafe_id,invoice_line_id) REFERENCES public.bf_document_lines(cafe_id,id));
CREATE INDEX erp_contracting_reversal_source ON public.erp_contracting_reversals(cafe_id,source_id);
CREATE INDEX erp_contracting_reverse_finance_line ON public.erp_contracting_reverse_lines(cafe_id,invoice_line_id);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_contracting_reversals','erp_contracting_reverse_lines'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
 EXECUTE format('CREATE TRIGGER cancellation_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION brand_cancellation_private.guard_archive()',t);
 EXECUTE format('CREATE POLICY cancellation_archive_scope ON public.%I AS RESTRICTIVE FOR ALL TO anon,authenticated USING(public.brand_account_not_cancelled(cafe_id) OR public.is_platform_admin()) WITH CHECK(public.brand_account_not_cancelled(cafe_id))',t);
END LOOP;END $$;
-- Quantity/recovery deductions are new documents, never updates to historical certificates
CREATE FUNCTION erp_contracting_private.reversed_quantity(c uuid,contract_id uuid,line_id uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path='' AS $$SELECT coalesce(sum(l.quantity),0) FROM public.erp_contracting_documents r JOIN public.erp_contracting_documents s ON s.cafe_id=r.cafe_id AND s.id=r.source_id JOIN public.erp_contracting_lines l ON l.cafe_id=r.cafe_id AND l.document_id=r.id JOIN public.erp_contracting_lines sl ON sl.cafe_id=l.cafe_id AND sl.document_id=s.id AND sl.id=l.source_line_id WHERE r.cafe_id=c AND r.kind='reverse_certificate' AND r.status='approved' AND s.source_id=contract_id AND sl.source_line_id=line_id$$;
CREATE FUNCTION erp_contracting_private.reversed_recovery(c uuid,contract_id uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path='' AS $$SELECT coalesce(sum(r.recovery),0) FROM public.erp_contracting_documents r JOIN public.erp_contracting_documents s ON s.cafe_id=r.cafe_id AND s.id=r.source_id WHERE r.cafe_id=c AND r.kind='reverse_certificate' AND r.status='approved' AND s.source_id=contract_id$$;
-- Preserve the current applied role and branch wrappers
DO $$DECLARE src text;BEGIN
 SELECT pg_get_functiondef('erp_access_private.snapshot_erp_contracting(uuid,text,jsonb,uuid)'::regprocedure) INTO src;
 IF position('IF used>source_line.quantity' IN src)=0 THEN RAISE EXCEPTION 'Contract quantity anchor missing';END IF;
 src:=replace(src,'IF used>source_line.quantity','used:=used-erp_contracting_private.reversed_quantity(p_cafe_id,src.id,source_line.id);IF used>source_line.quantity');
 src:=replace(src,'FOREACH kind_name IN ARRAY ARRAY[''bid'',''project'',''cost_sheet'',''quotation'',''contract'',''certificate'',''work_item'']','FOREACH kind_name IN ARRAY ARRAY[''bid'',''project'',''cost_sheet'',''quotation'',''contract'',''certificate'',''reverse_certificate'',''work_item'']');
 src:=replace(src,'greatest(0,src.advance_amount-used)','greatest(0,src.advance_amount-used+erp_contracting_private.reversed_recovery(p_cafe_id,src.id))');
 EXECUTE replace(src,'erp_access_private.snapshot_erp_contracting(','erp_contracting_private.before_reverse(');
END $$;
DO $$DECLARE src text;BEGIN
 SELECT pg_get_functiondef('brand_finance_private.refund_lines(uuid,uuid,boolean)'::regprocedure) INTO src;EXECUTE replace(src,'brand_finance_private.refund_lines(','erp_contracting_private.refund_lines_before_reverse(');
 SELECT pg_get_functiondef('brand_finance_private.credit_note_validate(uuid,jsonb,boolean)'::regprocedure) INTO src;EXECUTE replace(src,'brand_finance_private.credit_note_validate(','erp_contracting_private.credit_validate_before_reverse(');
 SELECT pg_get_functiondef('brand_finance_private.contracting_record(uuid,uuid)'::regprocedure) INTO src;EXECUTE replace(src,'brand_finance_private.contracting_record(','erp_contracting_private.record_before_reverse(');
END $$;
CREATE OR REPLACE FUNCTION brand_finance_private.refund_lines(p_cafe uuid,p_doc uuid,p_managed boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE result jsonb;BEGIN
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('returned_quantity',coalesce((x->>'returned_quantity')::numeric,0)+coalesce(r.q,0),'returned_net',coalesce((x->>'returned_net')::numeric,0)+coalesce(r.net,0),'returned_tax',coalesce((x->>'returned_tax')::numeric,0)+coalesce(r.tax,0))),'[]') INTO result FROM jsonb_array_elements(erp_contracting_private.refund_lines_before_reverse(p_cafe,p_doc,p_managed)) x LEFT JOIN LATERAL(SELECT sum(l.quantity) q,sum(l.net) net,sum(l.tax) tax FROM public.erp_contracting_reverse_lines l JOIN public.erp_contracting_reversals r ON r.cafe_id=l.cafe_id AND r.document_id=l.document_id JOIN public.erp_contracting_documents rd ON rd.cafe_id=r.cafe_id AND rd.id=r.document_id AND rd.status='approved' LEFT JOIN public.bf_credit_notes n ON n.cafe_id=r.cafe_id AND n.id=r.credit_note_id WHERE (r.credit_note_id IS NULL OR n.status='issued') AND l.cafe_id=p_cafe AND l.invoice_line_id=(x->>'id')::uuid) r ON true;RETURN result;
END $$;
CREATE OR REPLACE FUNCTION brand_finance_private.contracting_record(p_cafe uuid,p_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT erp_contracting_private.record_before_reverse(p_cafe,p_id)||coalesce((SELECT jsonb_build_object('credit_note_id',credit_note_id,'credit_document_id',credit_document_id,'credit_allocation_id',allocation_id) FROM public.erp_contracting_reversals WHERE cafe_id=p_cafe AND document_id=p_id),'{}')$$;
CREATE FUNCTION erp_contracting_private.credit_payload(c uuid,rid uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('partyId',d.customer_id,'warehouseId','','date',coalesce(nullif(d.details->>'date',''),current_date::text),'issueDate',current_date,'salespersonId',NULL,'sourceInvoiceId',s.invoice_id,'reason',left(d.title,500),'note',left(d.details->>'description',1000),'terms','','template','standard','deliveryMethod','print','stockRequired',false,'discountValue',0,'discountKind','amount','vatRate',0,'taxInclusive',false,'lines',(SELECT jsonb_agg(jsonb_build_object('key',l.position,'productId','','quantity',l.quantity,'price',l.unit_price,'description',left(l.name,500),'vatRate',l.tax_rate) ORDER BY l.position) FROM public.erp_contracting_lines l WHERE l.cafe_id=c AND l.document_id=rid)) FROM public.erp_contracting_documents d JOIN public.erp_contracting_documents s ON s.cafe_id=d.cafe_id AND s.id=d.source_id WHERE d.cafe_id=c AND d.id=rid$$;
CREATE OR REPLACE FUNCTION brand_finance_private.credit_note_validate(cafe uuid,p jsonb,strict_refs boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE rid uuid;v jsonb;rows jsonb;net numeric;tax numeric;BEGIN
 rid:=nullif(current_setting('erp.contracting_reverse',true),'')::uuid;
 IF rid IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_contracting_reversals r JOIN public.erp_contracting_documents d ON d.cafe_id=r.cafe_id AND d.id=r.document_id WHERE r.cafe_id=cafe AND r.document_id=rid AND r.credit_note_id IS NOT NULL AND d.status='issued' AND d.kind='reverse_certificate') THEN RETURN erp_contracting_private.credit_validate_before_reverse(cafe,p,strict_refs);END IF;
 IF p IS DISTINCT FROM erp_contracting_private.credit_payload(cafe,rid) THEN RAISE EXCEPTION 'Reverse credit payload changed' USING ERRCODE='40001';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=cafe AND id=(p->>'partyId')::uuid AND active AND kind='customer') THEN RAISE EXCEPTION 'Reverse customer unavailable' USING ERRCODE='42501';END IF;
 v:=erp_contracting_private.credit_validate_before_reverse(cafe,p,false);
 SELECT jsonb_agg(jsonb_build_object('productId','','name',l.name,'description',l.note,'itemId',NULL,'unitCost',0,'components','[]'::jsonb,'quantity',l.quantity,'price',l.unit_price,'discount',0,'net',m.net,'tax',m.tax,'total',m.net+m.tax,'vatRate',l.tax_rate) ORDER BY l.position),sum(m.net),sum(m.tax) INTO rows,net,tax FROM public.erp_contracting_lines l JOIN public.erp_contracting_reverse_lines m ON m.cafe_id=l.cafe_id AND m.document_id=l.document_id AND m.line_id=l.id WHERE l.cafe_id=cafe AND l.document_id=rid;
 IF net+tax<=0 THEN RAISE EXCEPTION 'Reverse amount must be positive' USING ERRCODE='22023';END IF;RETURN v||jsonb_build_object('lines',rows,'subtotal',net,'discount',0,'tax',tax,'total',net+tax);
END $$;
-- Deterministic one-to-one mapping handles repeated identical service rows without inventing products
CREATE FUNCTION erp_contracting_private.invoice_line(c uuid,certificate uuid,line uuid) RETURNS uuid LANGUAGE sql STABLE SET search_path='' AS $$WITH cert AS(SELECT l.*,row_number() OVER(PARTITION BY name,quantity,round(unit_price,2),round(quantity*unit_price,2),round(round(quantity*unit_price,2)*tax_rate/100,2) ORDER BY position,id) rn FROM public.erp_contracting_lines l WHERE cafe_id=c AND document_id=certificate AND kind='work' AND quantity>0),invoice AS(SELECT l.*,row_number() OVER(PARTITION BY name,quantity,unit_price,net,tax ORDER BY id) rn FROM public.bf_document_lines l WHERE cafe_id=c AND document_id=(SELECT invoice_id FROM public.erp_contracting_documents WHERE cafe_id=c AND id=certificate)) SELECT i.id FROM cert l JOIN invoice i ON i.name=l.name AND i.quantity=l.quantity AND i.unit_price=round(l.unit_price,2) AND i.net=round(l.quantity*l.unit_price,2) AND i.tax=round(round(l.quantity*l.unit_price,2)*l.tax_rate/100,2) AND i.rn=l.rn WHERE l.id=line AND i.product_id IS NULL AND i.item_id IS NULL$$;
CREATE OR REPLACE FUNCTION brand_finance_private.contracting_record(p_cafe uuid,p_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT erp_contracting_private.record_before_reverse(p_cafe,p_id)||coalesce((SELECT jsonb_build_object('credit_note_id',credit_note_id,'credit_document_id',credit_document_id,'credit_allocation_id',allocation_id) FROM public.erp_contracting_reversals WHERE cafe_id=p_cafe AND document_id=p_id),'{}')||coalesce((SELECT jsonb_build_object('reversible_quantities',coalesce((SELECT jsonb_object_agg(l.id,greatest(0,(v->>'quantity')::numeric-(v->>'returned_quantity')::numeric)) FROM public.erp_contracting_lines l JOIN LATERAL jsonb_array_elements(brand_finance_private.refund_lines(p_cafe,d.invoice_id,true)) v ON v->>'id'=erp_contracting_private.invoice_line(p_cafe,p_id,l.id)::text WHERE l.cafe_id=p_cafe AND l.document_id=p_id),'{}')) FROM public.erp_contracting_documents d WHERE d.cafe_id=p_cafe AND d.id=p_id AND d.kind='certificate' AND d.invoice_id IS NOT NULL),'{}')$$;
CREATE FUNCTION erp_contracting_private.calculate(c uuid,rid uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_variable
<<calculate>>
DECLARE d public.erp_contracting_documents;s public.erp_contracting_documents;l record;v jsonb;available jsonb;prior_net numeric;prior_ret numeric;prior_rec numeric;sub numeric:=0;tax numeric:=0;ret numeric;rec numeric;used numeric;BEGIN
 SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND id=rid FOR UPDATE;SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND id=d.source_id FOR UPDATE;
 IF s.kind<>'certificate' OR s.status<>'approved' OR s.invoice_id IS NULL OR d.customer_id IS DISTINCT FROM s.customer_id OR d.project_id IS DISTINCT FROM s.project_id THEN RAISE EXCEPTION 'Reverse source must be billed certificate' USING ERRCODE='22023';END IF;
 PERFORM erp_branch_private.assert_input(c,jsonb_build_object('id',s.id,'documentId',s.invoice_id));available:=brand_finance_private.refund_lines(c,s.invoice_id,true);
 DELETE FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid;
 FOR l IN SELECT * FROM public.erp_contracting_lines WHERE cafe_id=c AND document_id=rid ORDER BY position LOOP
  SELECT x INTO v FROM jsonb_array_elements(available)x WHERE x->>'id'=erp_contracting_private.invoice_line(c,s.id,l.source_line_id)::text;
  IF v IS NULL OR l.quantity<=0 OR l.quantity<>round(l.quantity,3) OR l.quantity>(v->>'quantity')::numeric-(v->>'returned_quantity')::numeric THEN RAISE EXCEPTION 'Reverse quantity exceeds remaining billed quantity' USING ERRCODE='22023';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid AND invoice_line_id=(v->>'id')::uuid) THEN RAISE EXCEPTION 'Duplicate reverse source line' USING ERRCODE='22023';END IF;
  INSERT INTO public.erp_contracting_reverse_lines VALUES(c,rid,l.id,(v->>'id')::uuid,l.quantity,round((v->>'net')::numeric*((v->>'returned_quantity')::numeric+l.quantity)/(v->>'quantity')::numeric,2)-(v->>'returned_net')::numeric,round((v->>'tax')::numeric*((v->>'returned_quantity')::numeric+l.quantity)/(v->>'quantity')::numeric,2)-(v->>'returned_tax')::numeric);
 END LOOP;
 SELECT sum(net),sum(erp_contracting_reverse_lines.tax) INTO sub,tax FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid;
 SELECT coalesce(sum(subtotal),0),coalesce(sum(retention),0),coalesce(sum(recovery),0) INTO prior_net,prior_ret,prior_rec FROM public.erp_contracting_documents WHERE cafe_id=c AND source_id=s.id AND kind='reverse_certificate' AND status='approved';
 ret:=least(s.retention-prior_ret,greatest(0,round(s.retention*(prior_net+sub)/nullif(s.subtotal,0),2)-prior_ret));rec:=least(s.recovery-prior_rec,greatest(0,round(s.recovery*(prior_net+sub)/nullif(s.subtotal,0),2)-prior_rec));
 SELECT coalesce(sum(total),0) INTO used FROM public.bf_credit_notes WHERE cafe_id=c AND source_invoice_id=s.invoice_id AND status='issued';SELECT used+coalesce(sum(total),0) INTO used FROM public.bf_documents WHERE cafe_id=c AND reference_id=s.invoice_id AND kind='refund';
 IF sub+tax<0 OR sub+tax+used>s.total THEN RAISE EXCEPTION 'Reverse amount exceeds source balance' USING ERRCODE='22023';END IF;
 UPDATE public.erp_contracting_documents SET subtotal=sub,tax=calculate.tax,total=sub+calculate.tax,retention=coalesce(ret,0),recovery=coalesce(rec,0),net_due=sub+calculate.tax-coalesce(ret,0)-coalesce(rec,0) WHERE cafe_id=c AND id=rid;
END $$;
CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_contracting(p_cafe_id uuid,p_action text DEFAULT 'read',p_input jsonb DEFAULT '{}',p_request_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
<<snapshot_erp_contracting>>
DECLARE c uuid:=p_cafe_id;d public.erp_contracting_documents;s public.erp_contracting_documents;l jsonb;sl public.erp_contracting_lines;id uuid:=nullif(p_input->>'id','')::uuid;prior jsonb;result jsonb;cmd jsonb;num text;n bigint;pos integer:=0;payload jsonb;credit uuid;allocation uuid;amount numeric;old_context text;role_name text;BEGIN
 SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id;
 IF NOT((p_action='save' AND p_input->>'kind'='reverse_certificate') OR (p_action='transition' AND d.kind='reverse_certificate') OR (p_action='transition' AND p_input->>'status'='issued' AND d.kind IN('certificate','cost_sheet','quotation'))) THEN RETURN erp_contracting_private.before_reverse(c,p_action,p_input,p_request_id);END IF;
 role_name:=brand_finance_private.role_for(c);IF coalesce(role_name,'') NOT IN('owner','manager','accountant') OR NOT public.brand_account_not_cancelled(c) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(c::text,67131));
 SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id FOR UPDATE;
 PERFORM erp_access_private.assert_allowed(c,'contracting',CASE WHEN p_action='save' THEN CASE WHEN d.id IS NULL THEN 'create' ELSE 'update' END ELSE 'approve' END);PERFORM erp_branch_private.assert_context(c);PERFORM erp_branch_private.assert_input(c,p_input);
 IF d.id IS NOT NULL THEN PERFORM erp_branch_private.assert_input(c,to_jsonb(d));END IF;IF d.kind='reverse_certificate' THEN SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=d.source_id;IF s.id IS NULL THEN RAISE EXCEPTION 'Reverse source unavailable' USING ERRCODE='42501';END IF;PERFORM erp_branch_private.assert_input(c,to_jsonb(s));END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>700000 THEN RAISE EXCEPTION 'Invalid request';END IF;
 cmd:=jsonb_build_object('action',p_action,'input',p_input,'actor',auth.uid());SELECT command,r.result INTO prior,result FROM public.erp_contracting_requests r WHERE cafe_id=c AND r.id=p_request_id;IF FOUND THEN IF prior<>cmd THEN RAISE EXCEPTION 'Request changed' USING ERRCODE='40001';END IF;RETURN result;END IF;
 SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id FOR UPDATE;
 IF coalesce(d.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
 IF p_action='save' THEN
  SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=(p_input->>'source_id')::uuid FOR UPDATE;
  IF id IS NULL OR (d.id IS NOT NULL AND (d.kind<>'reverse_certificate' OR d.status NOT IN('draft','issued'))) OR s.kind IS DISTINCT FROM 'certificate' OR s.invoice_id IS NULL OR s.status<>'approved' OR (d.id IS NOT NULL AND d.source_id<>s.id) THEN RAISE EXCEPTION 'Reverse source must be billed certificate' USING ERRCODE='22023';END IF;
  IF length(btrim(coalesce(p_input->>'title',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p_input->'lines')<>'array' OR jsonb_array_length(p_input->'lines') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid reverse document' USING ERRCODE='22023';END IF;
  PERFORM erp_branch_private.assert_input(c,to_jsonb(s));num:=coalesce(d.number,nullif(trim(p_input->>'number'),''));
  IF num IS NULL THEN INSERT INTO public.erp_contracting_settings(cafe_id) VALUES(c) ON CONFLICT DO NOTHING;SELECT coalesce((settings#>>'{numbering,reverse_certificate}')::bigint,1) INTO n FROM public.erp_contracting_settings WHERE cafe_id=c;WHILE EXISTS(SELECT 1 FROM public.erp_contracting_documents WHERE cafe_id=c AND kind='reverse_certificate' AND number=lpad(n::text,greatest(6,length(n::text)),'0')) LOOP n:=n+1;END LOOP;num:=lpad(n::text,greatest(6,length(n::text)),'0');UPDATE public.erp_contracting_settings SET settings=jsonb_set(jsonb_set(settings,'{numbering}',coalesce(settings->'numbering','{}'),true),'{numbering,reverse_certificate}',to_jsonb(n+1),true) WHERE cafe_id=c;END IF;
  INSERT INTO public.erp_contracting_documents(cafe_id,id,kind,title,number,status,customer_id,project_id,source_id,details,actor) VALUES(c,id,'reverse_certificate',p_input->>'title',num,CASE WHEN coalesce((p_input->>'draft')::boolean,false) THEN 'draft' ELSE 'issued' END,s.customer_id,s.project_id,s.id,p_input-ARRAY['id','kind','title','number','revision','status','customer_id','project_id','source_id','lines','draft'],auth.uid()) ON CONFLICT ON CONSTRAINT erp_contracting_documents_pkey DO UPDATE SET title=excluded.title,status=excluded.status,details=excluded.details,revision=erp_contracting_documents.revision+1,updated_at=clock_timestamp();
  INSERT INTO public.erp_contracting_reversals(cafe_id,document_id,source_id) VALUES(c,id,s.id) ON CONFLICT DO NOTHING;
  DELETE FROM public.erp_contracting_lines WHERE cafe_id=c AND document_id=id;
  FOR l IN SELECT value FROM jsonb_array_elements(p_input->'lines') LOOP
   SELECT * INTO sl FROM public.erp_contracting_lines WHERE cafe_id=c AND document_id=s.id AND erp_contracting_lines.id=(l->>'source_line_id')::uuid AND kind='work';IF sl.id IS NULL OR (l->>'quantity')::numeric<=0 THEN RAISE EXCEPTION 'Invalid reverse source line' USING ERRCODE='22023';END IF;pos:=pos+1;
   INSERT INTO public.erp_contracting_lines(cafe_id,document_id,id,position,source_line_id,kind,name,unit,note,quantity,unit_price,markup,tax_rate) VALUES(c,id,(l->>'id')::uuid,pos,sl.id,'work',sl.name,sl.unit,coalesce(l->>'note',''),(l->>'quantity')::numeric,coalesce((SELECT unit_price FROM public.bf_document_lines WHERE cafe_id=c AND bf_document_lines.id=erp_contracting_private.invoice_line(c,s.id,sl.id)),sl.unit_price),0,sl.tax_rate);
  END LOOP;PERFORM erp_contracting_private.calculate(c,id);
 ELSE
  IF p_input->>'status'='issued' THEN
   IF d.kind='reverse_certificate' OR d.status<>'approved' OR d.invoice_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=c AND draft_id=d.invoice_draft_id) OR EXISTS(SELECT 1 FROM public.erp_contracting_documents WHERE cafe_id=c AND source_id=d.id AND status NOT IN('cancelled','rejected')) THEN RAISE EXCEPTION 'Billed or linked approval cannot be revoked' USING ERRCODE='22023';END IF;
   UPDATE public.erp_contracting_documents SET status='issued',revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
  ELSIF d.kind='reverse_certificate' AND p_input->>'status'='approved' THEN
   IF d.status<>'issued' THEN RAISE EXCEPTION 'Reverse must be issued before approval' USING ERRCODE='22023';END IF;PERFORM erp_access_private.assert_allowed(c,'finance','approve');
   PERFORM erp_contracting_private.calculate(c,id);SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id;SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=d.source_id;
   result:='{}';IF d.total>0 THEN credit:=gen_random_uuid();UPDATE public.erp_contracting_reversals SET credit_note_id=credit WHERE cafe_id=c AND document_id=id;old_context:=current_setting('erp.contracting_reverse',true);PERFORM set_config('erp.contracting_reverse',id::text,true);payload:=erp_contracting_private.credit_payload(c,id);
   PERFORM public.brand_finance_save_credit_note(c,credit,0,payload);result:=public.brand_finance_transition_credit_note(c,credit,1,'issue',gen_random_uuid(),'');
   amount:=least(greatest(0,d.total-d.recovery),greatest(0,(brand_finance_private.document_state(c,s.invoice_id)->>'outstanding')::numeric));IF amount>0 THEN allocation:=brand_finance_private.customer_credit_apply(c,s.invoice_id,amount);END IF;
   IF to_regprocedure('erp_settings_private.reverse_advance_recovery(uuid,uuid,uuid,numeric)') IS NOT NULL THEN PERFORM erp_settings_private.reverse_advance_recovery(c,s.invoice_id,id,d.recovery);END IF;
   UPDATE public.erp_contracting_reversals SET credit_document_id=(result->>'journalId')::uuid,allocation_id=allocation WHERE cafe_id=c AND document_id=id;PERFORM set_config('erp.contracting_reverse',coalesce(old_context,''),true);END IF;
   UPDATE public.erp_contracting_documents SET status='approved',invoice_id=(result->>'journalId')::uuid,revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
   IF d.project_id IS NOT NULL AND d.total>0 THEN INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation,amount) VALUES(c,d.project_id,(result->>'journalId')::uuid,'certificate_reversal',d.total);END IF;
  ELSIF d.kind='reverse_certificate' AND d.status IN('draft','issued') AND p_input->>'status'='cancelled' THEN UPDATE public.erp_contracting_documents SET status='cancelled',revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
  ELSE RAISE EXCEPTION 'Invalid reverse transition' USING ERRCODE='22023';END IF;
 END IF;
 result:=jsonb_build_object('id',id,'revision',(SELECT revision FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id));INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(c,id,CASE WHEN p_action='save' THEN 'reverse_saved' ELSE 'transition:'||(p_input->>'status') END,'',auth.uid());INSERT INTO public.erp_contracting_requests VALUES(c,p_request_id,cmd,result);RETURN result;
END $$;
INSERT INTO erp_settings_private.number_contexts VALUES('contracting_reverse_certificate','المستخلصات العكسية','erp_contracting_documents','number','kind','reverse_certificate');
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_contracting_private FROM PUBLIC,anon,authenticated,service_role;
NOTIFY pgrst,'reload schema';
